#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int POT1_PIN = A3;  
const int POT2_PIN = A4;  
const byte segmentCodes[] = {
  0b11000000,  
  0b11111001,  
  0b10100100,  
  0b10110000,  
  0b10011001,  
  0b10010010,  
  0b10000010,  
  0b11111000,  
  0b10000000,  
  0b10010000,  
};

void setup();
void loop();
void displayNumber(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  displayNumber(0);  
}
void loop() {
  int pot1Value = analogRead(POT1_PIN);  
  int pot2Value = analogRead(POT2_PIN);  
  int tens = map(pot1Value, 0, 1023, 0, 9);  
  int units = map(pot2Value, 0, 1023, 0, 9);  
  int sum = tens + units;  
  int displayValue = sum % 10;  
  displayNumber(displayValue);  
  delay(200);  
}
void displayNumber(int number) {
  byte code = segmentCodes[number];  
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, code);  
  digitalWrite(STCP_PIN, HIGH);  
  digitalWrite(STCP_PIN, LOW);  
}
